{
  "description": "The creature is a slender, four-legged equine animal shown in strict right-facing profile against a plain off-white background. Its coat is a uniform light to medium brown with a paler cream-white underbelly, inner legs, and muzzle, and darker brown shading along the back, lower legs, and joints. It has a long, narrow head with a white nose and mouth area, a dark eye, and two large upright ears, a short stiff dark brown mane along the top of the neck, a lean torso with visible musculature and skin folds at the neck and chest, four straight slender legs ending in single hooves standing on a flat surface with faint shadows, and a thin hanging tail with a dark hair tuft at the tip.",
  "parts": [
    {
      "part": "head",
      "looks_like": "elongated equine head with a brown face, white to light gray around the nostrils, mouth and lower lip, a dark eye with a light ring, and a slightly downturned muzzle with visible nostril and whiskers",
      "where": "at the front/right end of the body, attached to the neck, facing right in profile"
    },
    {
      "part": "ears",
      "looks_like": "two large, upright, pointed ears with brown outer fur, lighter cream inner fur, and dark rims and tips, the near ear fully visible and the far ear slightly behind it",
      "where": "on top of the head, one on each side of the crown, pointing upward"
    },
    {
      "part": "mane",
      "looks_like": "short, stiff, upright brush of dark brown to black hair, evenly cut and dense",
      "where": "along the dorsal midline of the neck, running from just behind the ears to the top of the shoulders"
    },
    {
      "part": "legs",
      "looks_like": "four slender, straight legs with visible joints, tendons and slight wrinkling at the knees and hocks, brown with lighter inner surfaces, the near fore and hind legs in front and the far fore and hind legs offset slightly behind them",
      "where": "beneath the torso, two forelegs under the chest and two hindlegs under the hips, extending vertically to the ground"
    },
    {
      "part": "feet",
      "looks_like": "four single, rounded hooves, light gray-brown with darker worn edges and a slightly flared base, each at the tip of a leg",
      "where": "at the bottom of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "thin tail with short brown hair along its length and a longer, darker brown to black tuft of coarse hair at the end, hanging straight down with a slight curve",
      "where": "extending from the rear/left end of the rump, hanging vertically downward"
    },
    {
      "part": "markings",
      "looks_like": "pale cream-white patch covering the nostrils, muzzle and lower lip, and lighter cream shading on the underbelly, chest, and inner thighs, contrasting with the medium brown body and dark brown mane and tail tuft",
      "where": "on the face around the nose and mouth, and on the ventral side of the torso and inner legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "donkey"
  ],
  "separate_bodies": 1,
  "heads": 1,
